const state = {items:[], moves:[], units:['adet','takım','paket','kutu','grup','metre','kg','litre'], token:'', adminKey:'', pendingAuthAction:null, lang:typeof document !== 'undefined' ? 'kz' : 'tr', page:'inventory', view:'grid', offset:0, limit:15, query:'', category:'', status:'', sort:'newest', editId:null, photo:null, photoRemoved:false, photoBusy:false, photoJob:0, moveId:null, kind:'giriş', detailId:null, ready:false};
try {
  state.view = localStorage.getItem('atolye-view-v2') === 'list' ? 'list' : 'grid';
  const savedLang = localStorage.getItem('atolye-lang');
  if (savedLang && UI[savedLang]) state.lang = savedLang;
  state.adminKey = sessionStorage.getItem('atolye-admin-key') || localStorage.getItem('atolye-admin-key') || '';
} catch (_) {}

const L = () => UI[state.lang] || UI.kz;
const fmt = v => new Intl.NumberFormat(L().locale, {maximumFractionDigits:3}).format(v);
const date = v => { const d = new Date(v); return Number.isNaN(d.valueOf()) ? '—' : d.toLocaleString(L().locale, {day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',year:'numeric'}); };
const code = id => 'MZ-'+String(id).padStart(4,'0');
const normalize = v => String(v ?? '').toLocaleLowerCase('tr-TR').normalize('NFKC').replace(/[ıişğüöç]/g,c=>({'ı':'i','i':'i','ş':'s','ğ':'g','ü':'u','ö':'o','ç':'c'}[c])).trim();
const uid = () => globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);

function tUnit(u) { return state.lang === 'tr' ? u : (I18N_DATA.units?.[u]?.[state.lang] || u); }
function tCat(c) { return state.lang === 'tr' ? c : (I18N_DATA.categories?.[c]?.[state.lang] || c); }
function tKind(k) { return state.lang === 'tr' ? k : (I18N_DATA.kinds?.[k]?.[state.lang] || k); }
function tLoc(loc) { return (!loc || state.lang === 'tr') ? loc : (I18N_DATA.locations?.[loc]?.[state.lang] || loc); }
function tVNote(vn) { return (!vn || state.lang === 'tr') ? vn : (I18N_DATA.verification_notes?.[vn]?.[state.lang] || vn); }
function tMoveNote(n) { return (!n || state.lang === 'tr') ? n : (I18N_DATA.move_notes?.[n]?.[state.lang] || n); }
function tItem(item) {
  if (!item || state.lang === 'tr') return {name:item?.name||'', model:item?.model||'', notes:item?.notes||'', category:item?.category||'', location:item?.location||'', unit:item?.unit||'', verification_note:item?.verification_note||''};
  const entryObj = I18N_DATA.items?.[item.name];
  const entry = entryObj?.[state.lang];
  const kzEntry = entryObj?.kz;
  let name = entry ? entry[0] : item.name;
  let model = (entry && (!kzEntry || item.model === kzEntry[1])) ? entry[1] : item.model;
  let notes = (entry && (!kzEntry || item.notes === kzEntry[2])) ? entry[2] : item.notes;
  if (state.lang === 'kz' && kzEntry && item.name === kzEntry[0]) {
    name = item.name;
    model = item.model;
    notes = item.notes;
  }
  if (item.name === 'FPV gözlük' && I18N_DATA.models?.[item.model]?.[state.lang]) {
    const mEntry = I18N_DATA.models[item.model][state.lang];
    model = mEntry[0];
    notes = mEntry[1];
  }
  return { name, model, notes, category: tCat(item.category), location: tLoc(item.location), unit: tUnit(item.unit), verification_note: tVNote(item.verification_note) };
}
function tItemNameByName(rawName) {
  if (!rawName || state.lang === 'tr') return rawName;
  const entry = I18N_DATA.items?.[rawName]?.[state.lang];
  return entry ? entry[0] : rawName;
}

function saveStaticDb() {
  try {
    localStorage.setItem('atolye-static-db-v1', JSON.stringify({items: state.items, moves: state.moves}));
  } catch (_) {}
}
function checkStaticAdmin(headers, body) {
  const k = ((headers && headers['X-Admin-Key']) || (body && body.admin_key) || state.adminKey || '').trim().toLowerCase();
  if (k !== 'ashyqaspan') {
    const err = new Error('Рұқсат кілті қате! / Неверный ключ доступа! (ashyqaspan)');
    err.status = 403;
    err.auth_required = true;
    state.adminKey = '';
    try { sessionStorage.removeItem('atolye-admin-key'); localStorage.removeItem('atolye-admin-key'); } catch (_) {}
    updateAuthUI();
    throw err;
  }
}
async function staticApi(path, options = {}) {
  const method = (options.method || 'GET').toUpperCase();
  const body = options.body ? JSON.parse(options.body) : {};
  const headers = options.headers || {};
  if (path === '/api/items' && method === 'GET') return state.items;
  if (path === '/api/movements' && method === 'GET') return state.moves;
  if (path === '/api/auth' && method === 'POST') {
    checkStaticAdmin(headers, body);
    return {ok: true};
  }
  if (path === '/api/items' && method === 'POST') {
    const nextId = state.items.reduce((m, i) => Math.max(m, i.id), 0) + 1;
    const nowIso = new Date().toISOString();
    const q = Number(body.quantity || 0);
    const newItem = {
      id: nextId,
      name: String(body.name || '').trim(),
      category: String(body.category || 'Басқа заттар').trim(),
      model: String(body.model || '').trim(),
      unit: body.unit || 'adet',
      quantity: q,
      minimum: Number(body.minimum || 0),
      location: String(body.location || '').trim(),
      notes: String(body.notes || '').trim(),
      verification_note: '',
      verified: !body.is_package,
      is_package: Boolean(body.is_package),
      photo: body.image ? ('data:image/jpeg;base64,' + body.image) : null,
      sources: [],
      archived: false,
      version: 1,
      created_at: nowIso,
      updated_at: nowIso
    };
    state.items.unshift(newItem);
    const nextMoveId = state.moves.reduce((m, r) => Math.max(m, r.id), 0) + 1;
    state.moves.unshift({id: nextMoveId, item_id: nextId, name: newItem.name, unit: newItem.unit, is_package: newItem.is_package, kind: 'kayıt', delta: q, balance: q, note: 'Алғашқы тіркеу', created_at: nowIso});
    saveStaticDb();
    return newItem;
  }
  const mItem = path.match(/^\/api\/items\/([0-9]+)(\/movements)?$/);
  if (mItem) {
    const id = Number(mItem[1]);
    checkStaticAdmin(headers, body);
    const idx = state.items.findIndex(i => i.id === id);
    if (idx < 0) throw new Error('Not found');
    const cur = state.items[idx];
    const nowIso = new Date().toISOString();
    if (method === 'DELETE' && !mItem[2]) {
      state.items.splice(idx, 1);
      state.moves = state.moves.filter(m => m.item_id !== id);
      saveStaticDb();
      return {deleted: id};
    }
    if (method === 'PATCH' && !mItem[2]) {
      const newQ = body.quantity !== undefined && body.quantity !== '' ? Number(body.quantity) : cur.quantity;
      if (newQ !== cur.quantity) {
        const nextMoveId = state.moves.reduce((m, r) => Math.max(m, r.id), 0) + 1;
        state.moves.unshift({id: nextMoveId, item_id: id, name: body.name || cur.name, unit: body.unit || cur.unit, is_package: Boolean(body.is_package ?? cur.is_package), kind: 'sayım', delta: Math.round((newQ - cur.quantity)*1000)/1000, balance: newQ, note: 'Түзету (Карточканы өңдеу)', created_at: nowIso});
      }
      const updated = {
        ...cur,
        name: body.name !== undefined ? String(body.name).trim() : cur.name,
        category: body.category !== undefined ? String(body.category).trim() : cur.category,
        model: body.model !== undefined ? String(body.model).trim() : cur.model,
        unit: body.unit || cur.unit,
        quantity: newQ,
        minimum: body.minimum !== undefined ? Number(body.minimum) : cur.minimum,
        location: body.location !== undefined ? String(body.location).trim() : cur.location,
        notes: body.notes !== undefined ? String(body.notes).trim() : cur.notes,
        archived: body.archived !== undefined ? Boolean(body.archived) : cur.archived,
        is_package: body.is_package !== undefined ? Boolean(body.is_package) : cur.is_package,
        photo: body.image ? ('data:image/jpeg;base64,' + body.image) : (body.remove_photo ? null : cur.photo),
        verified: newQ !== cur.quantity ? true : cur.verified,
        version: (cur.version || 1) + 1,
        updated_at: nowIso
      };
      state.items[idx] = updated;
      saveStaticDb();
      return updated;
    }
    if (method === 'POST' && mItem[2]) {
      const amount = Number(body.quantity || 0);
      const kind = body.kind;
      const balance = Math.round((kind === 'sayım' ? amount : cur.quantity + (kind === 'giriş' ? amount : -amount)) * 1000) / 1000;
      if (balance < 0) throw new Error(L().negStockErr);
      const delta = Math.round((balance - cur.quantity) * 1000) / 1000;
      cur.quantity = balance;
      if (kind === 'sayım') cur.verified = true;
      cur.updated_at = nowIso;
      cur.version = (cur.version || 1) + 1;
      const nextMoveId = state.moves.reduce((m, r) => Math.max(m, r.id), 0) + 1;
      state.moves.unshift({id: nextMoveId, item_id: id, name: cur.name, unit: cur.unit, is_package: cur.is_package, kind, delta, balance, note: String(body.note || '').trim(), created_at: nowIso});
      saveStaticDb();
      return cur;
    }
  }
  throw new Error('Unsupported static operation');
}
async function api(path, options = {}) {
  if (state.staticMode) return staticApi(path, options);
  const headers = {'Content-Type':'application/json','X-App-Token':state.token,...(options.headers||{})};
  if (state.adminKey && !headers['X-Admin-Key']) headers['X-Admin-Key'] = state.adminKey;
  const response = await fetch(path, {cache:'no-store', ...options, headers});
  const body = await response.json();
  if (!response.ok) {
    const err = new Error(body.error || 'Error');
    Object.assign(err, body, {status:response.status});
    if (err.auth_required) {
      state.adminKey = '';
      try { sessionStorage.removeItem('atolye-admin-key'); localStorage.removeItem('atolye-admin-key'); } catch (_) {}
      updateAuthUI();
    }
    throw err;
  }
  return body;
}
function updateAuthUI() {
  if (typeof document === 'undefined') return;
  const btn = $('#auth-btn');
  const txt = $('#auth-btn-text');
  if (!btn || !txt) return;
  const t = L();
  const unlocked = Boolean(state.adminKey);
  btn.classList.toggle('unlocked', unlocked);
  txt.textContent = unlocked ? t.authUnlocked : t.authLocked;
}
function requireAuth(actionFn) {
  if (state.adminKey) {
    actionFn();
    return;
  }
  state.pendingAuthAction = actionFn;
  if ($('#auth-form')) $('#auth-form').reset();
  if ($('#auth-error')) $('#auth-error').hidden = true;
  if ($('#auth-dialog')) {
    $('#auth-dialog').showModal();
    setTimeout(() => $('#auth-key-input')?.focus(), 30);
  }
}
function toggleAuthBtn() {
  const t = L();
  if (state.adminKey) {
    state.adminKey = '';
    try { sessionStorage.removeItem('atolye-admin-key'); localStorage.removeItem('atolye-admin-key'); } catch (_) {}
    updateAuthUI();
    toast(t.authLockedToast);
  } else {
    requireAuth(() => {});
  }
}
async function submitAuth(event) {
  event.preventDefault();
  const t = L();
  const key = ($('#auth-key-input')?.value || '').trim();
  if (!key) return;
  $('#auth-error').hidden = true;
  busy($('#auth-form'), true);
  try {
    await api('/api/auth', {method:'POST', headers:{'X-Admin-Key':key}, body:JSON.stringify({admin_key:key})});
    state.adminKey = key;
    try { sessionStorage.setItem('atolye-admin-key', key); localStorage.setItem('atolye-admin-key', key); } catch (_) {}
    updateAuthUI();
    $('#auth-dialog').close();
    toast(t.authUnlockedToast);
    const fn = state.pendingAuthAction;
    state.pendingAuthAction = null;
    if (fn) fn();
  } catch (err) {
    showError('#auth-error', err);
  } finally {
    busy($('#auth-form'), false);
  }
}
