function photoSrc(ph) {
  if (!ph) return '';
  if (ph.startsWith('data:') || ph.startsWith('http') || ph.startsWith('blob:')) return ph;
  return 'uploads/' + encodeURIComponent(ph);
}
function imageUrl(item) {return item.photo ? photoSrc(item.photo) : item.sources.length ? 'source_photos/'+encodeURIComponent(item.sources[0]) : '';}
