async function processPhoto(file) {
  if(!file)return;
  const job=++state.photoJob;
  if(file.size>30*1024*1024){showError('#item-error',new Error('Max 30 MB'));return;}
  if(!/^image\//.test(file.type)){showError('#item-error',new Error('Image required'));return;}
  state.photoBusy=true;$('#photo-zone').setAttribute('aria-busy','true');
  const url=URL.createObjectURL(file);
  try {
    const img=new Image();img.src=url;await img.decode();
    if(img.width*img.height>100000000)throw new Error('Resolution too large');
    const scale=Math.min(1,1600/Math.max(img.width,img.height));const canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));
    const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
    const encoded=canvas.toDataURL('image/jpeg',.85);
    if(job!==state.photoJob)return;
    state.photo=encoded.split(',')[1];state.photoRemoved=false;$('#photo-preview').src=encoded;$('#photo-preview').hidden=false;$('#photo-placeholder').hidden=true;$('#remove-photo').hidden=false;$('#item-error').hidden=true;
    if(state.aiAutoSave){state.aiAutoSave=false;setTimeout(()=>saveAiDraft(),40);return;}
    if(!$('#item-name').value)setTimeout(()=>$('#item-name').focus(),50);
  }catch(err){if(job===state.photoJob)showError('#item-error',new Error('JPEG/PNG/WebP required'));}
  finally{URL.revokeObjectURL(url);if(job===state.photoJob){state.photoBusy=false;$('#photo-zone').removeAttribute('aria-busy');}}
}
async function saveAiDraft() {
  const t = L();
  if(state.photoBusy)return;
  if(!state.photo && !state.editId) {
    state.aiAutoSave=true;
    $('#photo-file').click();
    return;
  }
  const form=$('#item-form');
  const stamp=new Date().toTimeString().slice(0,8).replace(/:/g,'')+'-'+Math.floor(100+Math.random()*900);
  if(!form.elements.name.value.trim()) form.elements.name.value='🤖 [AI толтырады #'+stamp+']';
  if(!form.elements.category.value.trim()) form.elements.category.value='🤖 AI Тексеру';
  if(!form.elements.model.value.trim()) form.elements.model.value='AI күтілуде';
  const curNotes=form.elements.notes.value.trim();
  if(!curNotes.includes('[AI_PENDING]')) form.elements.notes.value=curNotes?(curNotes+' [AI_PENDING]'):'[AI_PENDING] Фото бойынша AI толтырады';
  await submitItemForm(form, true);
}
function duplicates() {
  if(state.editId)return;
  const t = L();
  const name=normalize($('#item-name').value);
  const near=name.length>=2?state.items.filter(i=>{
    const tiName = normalize(tItem(i).name);
    const rawName = normalize(i.name);
    return tiName.includes(name)||name.includes(tiName)||rawName.includes(name)||name.includes(rawName);
  }).slice(0,4):[];
  const box=$('#duplicates');box.hidden=!near.length;
  box.innerHTML=`<strong>${t.dupWarning}</strong>`+near.map(i=>{
    const ti = tItem(i);
    return `<div class="duplicate-row"><span>${esc(ti.name)}<br>${fmt(i.quantity)} ${esc(ti.unit)} · ${esc(ti.model||code(i.id))}${i.archived?' · '+t.badgeArch:''}</span><button type="button" class="btn compact" data-action="${i.archived?'existing-detail':'existing-move'}" data-id="${i.id}">${i.archived?t.dupOpen:t.dupAdd}</button></div>`;
  }).join('');
}
async function saveItem(event) {
  event.preventDefault();const form=event.currentTarget;const next=event.submitter?.value==='next';
  await submitItemForm(form, next);
}
async function submitItemForm(form, next) {
  const t = L();
  if(state.photoBusy)return;
  $('#item-error').hidden=true;busy(form,true);
  const body=Object.fromEntries(new FormData(form));
  body.minimum=body.minimum||0;body.quantity=body.quantity||0;
  body.is_package=form.elements.is_package.checked;
  body.request_id=form.dataset.requestId;
  if(state.photo)body.image=state.photo;
  if(state.photoRemoved)body.remove_photo=true;
  if(state.editId){body.unit=form.elements.unit.value||find(state.editId).unit;body.allow_unit_change=true;body.version=Number(form.dataset.version);}
  try {
    const saved=await api(state.editId?'/api/items/'+state.editId:'/api/items',{method:state.editId?'PATCH':'POST',body:JSON.stringify(body)});
    $('#item-dialog').close();toast(t.savedToast+code(saved.id));
    try{await refresh(true);}catch(e){connected(false);}
    if(next)openItem();
  }catch(err){
    showError('#item-error',err);
    if(err.duplicate&&err.item_id){const i=find(err.item_id);if(i){const ti=tItem(i);$('#duplicates').hidden=false;$('#duplicates').innerHTML=`<strong>${esc(t.dupWarning)}</strong><div class="duplicate-row"><span>${esc(ti.name)} · ${fmt(i.quantity)} ${esc(ti.unit)}</span><button type="button" class="btn compact" data-action="${i.archived?'existing-detail':'existing-move'}" data-id="${i.id}">${t.dupSwitch}</button></div>`;}}
    if(err.status===409&&!err.duplicate){try{await refresh();}catch(_){} }
  }finally{busy(form,false);}
}

function openMove(id, kind='giriş') {
  requireAuth(() => _openMoveModal(id, kind));
}
function _openMoveModal(id, kind='giriş') {
  const i=find(id);if(!i)return;
  if(i.archived)return;
  const ti = tItem(i);
  state.moveId=i.id;$('#move-form').reset();$('#move-form').dataset.requestId=uid();$('#move-error').hidden=true;
  $('#move-summary').innerHTML=`<div><strong>${esc(ti.name)}</strong><small class="item-meta">${code(i.id)} · ${esc(ti.location||ti.category)}</small></div><span class="quantity">${fmt(i.quantity)} <span class="unit">${esc(ti.unit)}</span></span>`;
  setKind(kind);if($('#detail-dialog').open)$('#detail-dialog').close();$('#move-dialog').showModal();setTimeout(()=>$('#move-quantity').focus(),30);
}
function setKind(kind) {
  const t = L();
  state.kind=kind;$$('#move-kinds button').forEach(b=>b.classList.toggle('active',b.dataset.kind===kind));
  const item=find(state.moveId);
  const unitStr = item ? tUnit(item.unit) : '';
  $('#move-quantity-label').textContent=(kind==='giriş'?t.qtyInLbl:kind==='çıkış'?t.qtyOutLbl:t.qtyCntLbl)+' ('+unitStr+')';
  $('#move-quantity').min=kind==='sayım'?'0':'0.001';
  $('#move-hint').textContent=kind==='sayım'?t.hintCnt:kind==='giriş'?t.hintIn:t.hintOut;
  previewMove();
}
function previewMove() {
  const t = L();
  const item=find(state.moveId);if(!item)return;
  const unitStr = tUnit(item.unit);
  const raw=$('#move-quantity').value;const amount=Number(raw);const el=$('#move-result');
  const balance=Math.round((state.kind==='sayım'?amount:item.quantity+(state.kind==='giriş'?amount:-amount))*1000)/1000;
  el.classList.toggle('invalid',balance<0);
  el.textContent=!raw?t.curStock+fmt(item.quantity)+' '+unitStr:balance<0?t.negStockErr:t.afterStock+fmt(balance)+' '+unitStr;
}
async function saveMove(event) {
  event.preventDefault();const form=event.currentTarget;const i=find(state.moveId);if(!i)return;
  const t = L();
  $('#move-error').hidden=true;busy(form,true);
  try {
    const body={kind:state.kind,quantity:form.elements.quantity.value,note:form.elements.note.value,version:i.version,request_id:form.dataset.requestId};
    await api('/api/items/'+i.id+'/movements',{method:'POST',body:JSON.stringify(body)});
    $('#move-dialog').close();toast(state.kind==='sayım'?t.cntSavedToast:t.moveSavedToast);
    try{await refresh(true);}catch(e){connected(false);}
  }catch(err){showError('#move-error',err);if(err.status===409){try{await refresh();const latest=find(state.moveId);const tl=tItem(latest);$('#move-summary').innerHTML=`<strong>${esc(tl.name)}</strong><span class="quantity">${fmt(latest.quantity)} <span class="unit">${esc(tl.unit)}</span></span>`;previewMove();}catch(_){} }}
  finally{busy(form,false);}
}
async function detail(id) {
  const t = L();
  const i=find(id);if(!i)return;state.detailId=i.id;
  const ti = tItem(i);
  $('#detail-code').textContent=code(i.id)+' / '+ti.category;$('#detail-title').textContent=ti.name;
  $('#detail-content').innerHTML=`${i.photo?`<img class="detail-main-photo" src="${photoSrc(i.photo)}" alt="${esc(ti.name)}">`:''}${badge(i)}<div class="detail-stock"><div><small>${i.is_package?t.pkgQtySmall:t.curStockSmall}</small><span class="quantity">${fmt(i.quantity)} <span class="unit">${esc(ti.unit)}</span></span></div>${!i.archived?`<button class="btn primary" data-action="move" data-id="${i.id}">${icon('plus')}${t.updateStockBtn}</button>`:''}</div><div class="detail-actions"><button class="btn" data-action="edit" data-id="${i.id}">${icon('edit')}${t.editBtn}</button>${!i.archived?`<button class="btn" data-action="count" data-id="${i.id}">${icon('check')}${t.doCountBtn}</button>`:''}<button class="btn ghost" data-action="archive" data-id="${i.id}">${icon('archive')}${i.archived?t.unarchiveBtn:t.archiveBtn}</button><button class="btn danger-btn" data-action="delete" data-id="${i.id}">${icon('trash')}${t.deleteBtn}</button></div><dl class="detail-fields"><div><dt>${t.lblModel}</dt><dd>${esc(ti.model)||'—'}</dd></div><div><dt>${t.lblLoc}</dt><dd>${esc(ti.location)||t.notSpecified}</dd></div><div><dt>${t.lblMin}</dt><dd>${i.minimum?fmt(i.minimum)+' '+esc(ti.unit):t.alertOff}</dd></div><div><dt>${t.lastUpdate}</dt><dd>${date(i.updated_at)}</dd></div></dl>${ti.notes?`<h3>${t.itemNotesHdr}</h3><p class="detail-notes">${esc(ti.notes)}</p>`:''}${ti.verification_note?`<p class="reference-label">${t.initVerNote}${esc(ti.verification_note)}</p>`:''}${i.sources.length?`<h3>${t.srcPhotosHdr}</h3><p class="reference-label">${t.srcPhotosDesc}</p><div class="source-gallery">${i.sources.map(s=>`<a href="source_photos/${encodeURIComponent(s)}" target="_blank" rel="noopener"><img src="source_photos/${encodeURIComponent(s)}" alt="${esc(s)}" loading="lazy">${esc(s)}</a>`).join('')}</div>`:''}<h3>${t.stockHistHdr}</h3><ul class="detail-history" id="detail-history"><li>${t.loading}</li></ul>`;
  if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
  try {
    const all=await api('/api/movements');if(state.detailId!==i.id)return;
    const moves=all.filter(m=>m.item_id===i.id);
    $('#detail-history').innerHTML=moves.slice(0,100).map(m=>`<li><div><strong class="history-kind">${esc(tKind(m.kind))}</strong><small>${esc(tMoveNote(m.note))}</small><span class="meta">${date(m.created_at)}</span></div><div><strong class="${m.delta<0?'delta-out':'delta-in'}">${m.delta>0?'+':''}${fmt(m.delta)} ${esc(tUnit(m.unit))}</strong><small>${t.lastStock}${fmt(m.balance)}</small></div></li>`).join('')||`<li>${t.noMoves}</li>`;
  }catch(e){}
}
function confirmAction(title, message, label) {
  $('#confirm-title').textContent=title;$('#confirm-text').textContent=message;$('#confirm-ok').textContent=label;$('#confirm-error').hidden=true;$('#confirm-dialog').showModal();
  return new Promise(resolve=>{const dlg=$('#confirm-dialog');let answer=false;$('#confirm-ok').onclick=()=>{answer=true;dlg.close();};$('#confirm-cancel').onclick=()=>dlg.close();dlg.addEventListener('close',()=>resolve(answer),{once:true});});
}
function archive(id) {
  requireAuth(() => _doArchive(id));
}
async function _doArchive(id) {
  const t = L();
  const i=find(id);if(!i)return;
  const ti = tItem(i);
  const ok=await confirmAction(i.archived?t.unarchTitle:t.archTitle,i.archived?t.unarchMsg:(ti.name+t.archSuffix),i.archived?t.restoreAction:t.archiveBtn);
  if(!ok)return;
  try {
    await api('/api/items/'+i.id,{method:'PATCH',body:JSON.stringify({...i,archived:!i.archived})});
    $('#detail-dialog').close();await refresh();toast(i.archived?t.unarchivedToast:t.archivedToast);
  }catch(e){toast(e.message,true);}
}
function deleteItem(id) {
  requireAuth(() => _doDeleteItem(id));
}
async function _doDeleteItem(id) {
  const t = L();
  const i=find(id);if(!i)return;
  const ti = tItem(i);
  const ok=await confirmAction(t.delTitle, code(i.id)+' — '+ti.name+t.delSuffix, t.deleteBtn);
  if(!ok)return;
  try {
    await api('/api/items/'+i.id,{method:'DELETE'});
    if($('#item-dialog').open)$('#item-dialog').close();
    if($('#detail-dialog').open)$('#detail-dialog').close();
    await refresh(true);toast(t.deletedToast);
  }catch(e){toast(e.message,true);}
}
async function download(path, fallback, button) {
  const t = L();
  button.disabled=true;
  try {
    let targetPath = path;
    if (state.staticMode) {
      if (path.startsWith('/api/export.xlsx')) {
        targetPath = state.lang === 'ru' ? 'export_ru.xlsx' : 'export_kz.xlsx';
      } else if (path === '/api/backup.json') {
        targetPath = 'backup.json';
      }
    }
    const response=await fetch(targetPath,{cache:'no-store'});
    if(!response.ok){throw new Error('Error');}
    const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');
    a.href=url;a.download=response.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||fallback;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);
    toast(t.fileReadyToast);
  }catch(e){toast(e.message,true);}finally{button.disabled=false;}
}
async function restore(file) {
  if(!file)return;
  const t = L();
  if(file.size>120*1024*1024)return;
  let payload;
  try{payload=JSON.parse(await file.text());if(payload.format!=='atolye-envanter'||payload.version!==1||!Array.isArray(payload.items))throw new Error('Invalid');}
  catch(e){toast('JSON required',true);return;}
  requireAuth(async () => {
    const confirmed=await confirmAction(t.restoreConfirmTitle,t.restoreConfirmMsg,t.restoreBtn);
    if(!confirmed)return;
    $('#restore-btn').disabled=true;document.body.classList.add('busy');
    try {await api('/api/restore',{method:'POST',headers:{'X-Confirm-Restore':'replace'},body:JSON.stringify(payload)});await refresh(true);toast(t.restoreDoneToast);}
    catch(e){toast(e.message,true);}finally{$('#restore-btn').disabled=false;document.body.classList.remove('busy');$('#restore-file').value='';}
  });
}

function events() {
  $$('.nav').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
  $$('.lang-btn').forEach(b=>b.addEventListener('click',()=>setLang(b.dataset.lang)));
  $$('[data-stat]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.stat==='low'?'inventory':b.dataset.stat,b.dataset.stat==='low'?'low':'')));
  $('#add-btn').addEventListener('click',()=>openItem());$('#help-btn').addEventListener('click',()=>$('#help-dialog').showModal());
  if($('#auth-btn'))$('#auth-btn').addEventListener('click',toggleAuthBtn);
  if($('#auth-form'))$('#auth-form').addEventListener('submit',submitAuth);
  if($('#delete-item-btn'))$('#delete-item-btn').addEventListener('click',()=>{if(state.editId)deleteItem(state.editId);});
  $('#item-form').addEventListener('submit',saveItem);$('#move-form').addEventListener('submit',saveMove);
  $('#item-name').addEventListener('input',duplicates);
  $('#photo-file').addEventListener('change',e=>processPhoto(e.target.files[0]));
  if($('#gallery-btn'))$('#gallery-btn').addEventListener('click',()=>$('#gallery-file').click());
  if($('#gallery-file'))$('#gallery-file').addEventListener('change',e=>processPhoto(e.target.files[0]));
  if($('#ai-save-btn'))$('#ai-save-btn').addEventListener('click',saveAiDraft);
  $('#remove-photo').addEventListener('click',()=>{photoReset();state.photoRemoved=true;});
  const zone=$('#photo-zone');for(const event of ['dragenter','dragover'])zone.addEventListener(event,e=>{e.preventDefault();zone.classList.add('dragover');});
  for(const event of ['dragleave','drop'])zone.addEventListener(event,e=>{e.preventDefault();zone.classList.remove('dragover');});
  zone.addEventListener('drop',e=>processPhoto(e.dataTransfer.files[0]));
  $('#move-quantity').addEventListener('input',previewMove);$$('#move-kinds button').forEach(b=>b.addEventListener('click',()=>setKind(b.dataset.kind)));
  $('#search').addEventListener('input',e=>{state.query=e.target.value;state.offset=0;render();});
  $('#category-filter').addEventListener('change',e=>{state.category=e.target.value;state.offset=0;render();});
  $('#status-filter').addEventListener('change',e=>{state.status=e.target.value;state.offset=0;render();});
  $('#sort').addEventListener('change',e=>{state.sort=e.target.value;state.offset=0;render();});
  $('#clear-filters').addEventListener('click',()=>{state.query='';state.category='';state.status='';$('#search').value='';$('#category-filter').value='';$('#status-filter').value='';state.offset=0;render();});
  $('#prev-page').addEventListener('click',()=>{state.offset=Math.max(0,state.offset-state.limit);render();});
  $('#next-page').addEventListener('click',()=>{state.offset+=state.limit;render();});
  for(const mode of ['list','grid'])$('#view-'+mode).addEventListener('click',()=>{state.view=mode;try{localStorage.setItem('atolye-view-v2',mode);}catch(_){}render();});
  $('#excel-btn').addEventListener('click',()=>download('/api/export.xlsx?lang='+encodeURIComponent(state.lang),'Sheberhana_Envanter.xlsx',$('#excel-btn')));
  $('#backup-btn').addEventListener('click',()=>download('/api/backup.json','Sheberhana_Tam_Yedek.json',$('#backup-btn')));
  $('#restore-btn').addEventListener('click',()=>$('#restore-file').click());$('#restore-file').addEventListener('change',e=>restore(e.target.files[0]));
  document.addEventListener('click',e=>{
    const close=e.target.closest('[data-close]');if(close){close.closest('dialog').close();return;}
    const b=e.target.closest('[data-action]');if(!b)return;
    const id=Number(b.dataset.id);
    switch(b.dataset.action){
      case 'new':openItem();break;
      case 'detail':detail(id);break;
      case 'move':openMove(id);break;
      case 'count':openMove(id,'sayım');break;
      case 'edit':openItem(id);break;
      case 'archive':archive(id);break;
      case 'delete':deleteItem(id);break;
      case 'existing-move':$('#item-dialog').close();openMove(id);break;
      case 'existing-detail':$('#item-dialog').close();detail(id);break;
      case 'retry':location.reload();break;
    }
  });
  document.addEventListener('keydown',e=>{
    if(e.ctrlKey||e.metaKey||e.altKey||$('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))return;
    if(e.key==='/'){e.preventDefault();$('#search').focus();}
    if(e.key.toLowerCase()==='n'){e.preventDefault();openItem();}
  });
  for(const dlg of $$('dialog'))dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close();}});
}
async function boot() {
  events();
  applyLangUI();
  try {
    const data=await api('/api/bootstrap');state.token=data.token;state.items=data.items;state.units=data.units||state.units;state.ready=true;
    renderUnits();
    connected(true);options();stats();render();
  }catch(e){
    try {
      const snapResp = await fetch('data_snapshot.json', {cache:'no-store'});
      if (!snapResp.ok) throw new Error('No snapshot');
      const snap = await snapResp.json();
      state.staticMode = true;
      let saved = null;
      try { saved = JSON.parse(localStorage.getItem('atolye-static-db-v1') || 'null'); } catch (_) {}
      state.items = (saved && Array.isArray(saved.items)) ? saved.items : snap.items;
      state.moves = (saved && Array.isArray(saved.moves)) ? saved.moves : snap.moves;
      state.units = snap.units || state.units;
      state.ready = true;
      renderUnits();
      connected(true);options();stats();render();
      return;
    } catch (_) {}
    const t=L();connected(false);$('#records').innerHTML=`<div class="empty">${icon('alert')}<strong>${t.offlineTitle}</strong><p>${t.offlineDesc}</p><button class="btn primary" data-action="retry">${t.retryBtn}</button></div>`;$('#result-count').textContent=t.connOff;toast(e.message,true);
  }
}
boot();
